import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), capacity = nextInt();
        long[] stations = new long[n];
        HashSet<Long> occupied = new HashSet<>(4 * (n + capacity));
        for (int i = 0; i < n; i++) { stations[i] = nextLong(); occupied.add(stations[i]); }
        // Multi-source Dijkstra on the line: (distance, position), smallest first.
        PriorityQueue<long[]> frontier = new PriorityQueue<>((p, q) -> p[0] != q[0] ? Long.compare(p[0], q[0]) : Long.compare(p[1], q[1]));
        for (long s : stations) { frontier.add(new long[]{1, s - 1}); frontier.add(new long[]{1, s + 1}); }
        long total = 0;
        int bought = 0;
        while (bought < capacity) {
            long[] top = frontier.poll();
            if (!occupied.add(top[1])) continue; // a station or already bought
            total += top[0];
            bought++;
            frontier.add(new long[]{top[0] + 1, top[1] - 1});
            frontier.add(new long[]{top[0] + 1, top[1] + 1});
        }
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

type item struct{ dist, pos int }
type minHeap []item

func (h minHeap) Len() int { return len(h) }
func (h minHeap) Less(i, j int) bool {
	if h[i].dist != h[j].dist {
		return h[i].dist < h[j].dist
	}
	return h[i].pos < h[j].pos
}
func (h minHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)   { *h = append(*h, x.(item)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	n, capacity := readInt(), readInt()
	occupied := make(map[int]bool, 2*(n+capacity))
	frontier := &minHeap{}
	stations := make([]int, n)
	for i := range stations {
		stations[i] = readInt()
		occupied[stations[i]] = true
	}
	// Multi-source Dijkstra on the line: (distance, position), smallest first.
	for _, s := range stations {
		*frontier = append(*frontier, item{1, s - 1}, item{1, s + 1})
	}
	heap.Init(frontier)
	total, bought := 0, 0
	for bought < capacity {
		top := heap.Pop(frontier).(item)
		if occupied[top.pos] {
			continue // a station or already bought
		}
		occupied[top.pos] = true
		total += top.dist
		bought++
		heap.Push(frontier, item{top.dist + 1, top.pos - 1})
		heap.Push(frontier, item{top.dist + 1, top.pos + 1})
	}
	fmt.Println(total)
}
